-- One-time data migration from the local NexaFi SQLite database.
-- Generated by scripts/migrate-nexafi-sqlite.py. Run AFTER finance_setup.sql.
--
-- Safe to re-run only against an empty finance database: it inserts rows with
-- explicit ids and will collide with anything already imported.

do $$
declare
  owner_id uuid;
begin
  select id into owner_id from auth.users where email = 'nhambleton03@gmail.com';
  if owner_id is null then
    raise exception 'No Supabase auth user with email nhambleton03@gmail.com. Create the account first, then re-run.';
  end if;

  -- accounts -> fin_accounts (7 rows)

  -- transaction_categories -> fin_transaction_categories (22 rows)

  -- account_balances -> fin_account_balances (7 rows)

  -- transactions -> fin_transactions (9 rows)

  -- recurring_expenses -> fin_recurring_expenses (7 rows)

  -- sinking_funds -> fin_sinking_funds (1 rows)

  -- financial_goals -> fin_financial_goals (5 rows)

  -- retirement_contributions -> fin_retirement_contributions (1 rows)

  -- monthly_snapshots -> fin_monthly_snapshots (6 rows)

  -- settings -> fin_settings (33 rows)

  -- setup_progress absent in the source database
  -- (predates that table); recorded as complete because accounts exist.

end $$;

-- Move every identity sequence past the highest imported id, so the next
-- row created in the app does not collide with a migrated one.
select public.fin_resync_sequences();
